// F6-05: calcula las cuatro metricas del framework (tasa de ejecucion, tasa de error,
// latencia p95 y saturacion/cola) desde la serie Prometheus de la instancia y desde los
// errores registrados en Errores_CCB en la ultima hora.
const cfg = (() => { try { return $('Ejecutar Leer Configuración').first().json._config || {}; } catch (e) { return {}; } })();
const http = $('HTTP - Leer métricas').first().json;
const texto = String(http.data || http.body || '');
const num = (v) => Number(v);
const buckets = {};
let ok = 0, err = 0, sumaSeg = 0;
const gauge = {};
for (const linea of texto.split('\n')) {
  if (linea.startsWith('#') || !linea.trim()) continue;
  const m = linea.trim().match(/^([a-zA-Z0-9_:]+)(\{[^}]*\})?\s+(-?[\d.eE+-]+)$/);
  if (!m) continue;
  const nombre = m[1], labels = m[2] || '', valor = num(m[3]);
  if (nombre === 'n8n_workflow_execution_duration_seconds_bucket') {
    const le = (labels.match(/le="([^"]+)"/) || [])[1];
    const st = (labels.match(/status="([^"]+)"/) || [])[1];
    if (st === 'success') { const k = le === '+Inf' ? Infinity : num(le); buckets[k] = (buckets[k] || 0) + valor; }
  } else if (nombre === 'n8n_workflow_execution_duration_seconds_count') {
    const st = (labels.match(/status="([^"]+)"/) || [])[1];
    if (st === 'success') ok += valor; else if (st === 'failed') err += valor;
  } else if (nombre === 'n8n_workflow_execution_duration_seconds_sum') {
    sumaSeg += valor;
  } else if (nombre === 'n8n_nodejs_active_handles_total' || nombre === 'n8n_active_workflow_count'
             || nombre === 'n8n_nodejs_heap_size_used_bytes') {
    gauge[nombre] = valor;
  }
}
const total = ok + err;
let p95 = null, acumulado = 0;
for (const k of Object.keys(buckets).map(Number).sort((a, b) => a - b)) {
  acumulado = buckets[k];
  if (ok > 0 && acumulado >= ok * 0.95) { p95 = k; break; }
}
const ventana = $now.minus({ hours: 1 }).setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm:ss');
const filas = $input.all().map((i) => i.json);
const errores = filas.filter((f) => String(f.error_timestamp || '') >= ventana
  && !String(f.id_solicitud || '').startsWith('PRUEBA-') && f.workflow_origen !== 'verificacion');
const porFlujo = {};
for (const e of errores) { const k = e.workflow_origen || 'desconocido'; porFlujo[k] = (porFlujo[k] || 0) + 1; }
const tasa = total > 0 ? Number(((err / total) * 100).toFixed(2)) : 0;
const p95ms = (p95 === null || p95 === Infinity) ? null : Math.round(p95 * 1000);
const alertar = tasa >= 2 || errores.length >= 3;
const ahora = $now.setZone('America/Bogota').toFormat('yyyy-MM-dd HH:mm:ss');
const filasMetricas = [
  { metrica: 'tasa_error_pct', valor: String(tasa), unidad: 'porcentaje', estado: tasa >= 2 ? 'SUPERA_UMBRAL' : 'ok', actualizado_en: ahora },
  { metrica: 'ejecuciones_total', valor: String(total), unidad: 'ejecuciones', estado: 'ok', actualizado_en: ahora },
  { metrica: 'latencia_p95_ms', valor: String(p95ms === null ? '' : p95ms), unidad: 'milisegundos', estado: 'ok', actualizado_en: ahora },
  { metrica: 'saturacion_handles', valor: String(gauge['n8n_nodejs_active_handles_total'] ?? ''), unidad: 'handles_activos', estado: 'ok', actualizado_en: ahora },
  { metrica: 'errores_ultima_hora', valor: String(errores.length), unidad: 'errores', estado: errores.length >= 3 ? 'SUPERA_UMBRAL' : 'ok', actualizado_en: ahora },
];
const detalle = '<p><b>Monitoreo del pipeline CCB</b> (' + ahora + ')</p><ul>'
  + '<li><b>Tasa de error acumulada:</b> ' + tasa + '% (umbral 2%)</li>'
  + '<li><b>Ejecuciones desde el arranque:</b> ' + ok + ' ok / ' + err + ' con error</li>'
  + '<li><b>Latencia p95:</b> ' + (p95ms === null ? 'n/d' : p95ms + ' ms') + '</li>'
  + '<li><b>Saturacion (handles activos):</b> ' + (gauge['n8n_nodejs_active_handles_total'] ?? 'n/d') + '</li>'
  + '<li><b>Errores en la ultima hora:</b> ' + errores.length + (errores.length ? ' -> ' + JSON.stringify(porFlujo) : '') + '</li></ul>';
return { json: { tasa_error_pct: tasa, ejecuciones_total: total, errores_ultima_hora: errores.length,
                 latencia_p95_ms: p95ms, por_flujo: porFlujo, alertar, alertar_para: cfg.alertas_email,
                 unidad_alerta: cfg.asesor_email, detalle, metricas: filasMetricas } };

